use verus::prelude::*;

verus! {

    /// Deep‐clone a vector of u64s.
    /// 
    /// No preconditions.  The result has the same length as `arr`, and
    /// every element is equal.  Because we push each u64 by value,
    /// the returned Vec is independent of the original.
    fn list_deep_clone(arr: &Vec<u64>) -> (copied: Vec<u64>)
        ensures
            // same length
            copied.len() == arr.len(),
            // same contents
            forall |i: usize| i < arr.len() ==> copied[i] == arr[i],
    {
        // allocate a fresh Vec with enough capacity
        let mut copied = Vec::with_capacity(arr.len());
        let mut i: usize = 0;
        // copy elements one by one
        while i < arr.len() {
            invariant copied.len() == i;
            invariant forall |j: usize| j < i ==> copied[j] == arr[j];
            decreases arr.len() - i;
            copied.push(arr[i]);
            i += 1;
        }
        copied
    }

} // verus!  

